from jsonb_to_recordset($json$[{"brand_slug":"mesoestetic","slug":"centella-anti-inflammatory-repair-serum","title_zh_hk":"\u7a4d\u96ea\u8349\u6297\u708e\u4fee\u5fa9\u7cbe\u83ef","title_zh_cn":"\u79ef\u96ea\u8349\u6297\u708e\u4fee\u590d\u7cbe\u534e","title_en":"Centella Anti-Inflammatory Repair Serum","description_zh_hk":"<p>\u7a4d\u96ea\u8349\u6297\u708e\u4fee\u5fa9\u7cbe\u83ef\u914d\u65b9\u6eab\u548c\uff0c\u4f4e\u523a\u6fc0\uff0c\u7279\u5225\u9069\u5408\u654f\u611f\u808c\u819a\u4f7f\u7528\u3002\u7a4d\u96ea\u8349\u63d0\u53d6\u7269\u6709\u4fc3\u9032\u76ae\u819a\u53d7\u640d\u7d44\u7e54\u7652\u5408\u3001\u8212\u7de9\u53ca\u4fee\u5fa9\u808c\u819a\u7684\u529f\u6548\uff1b\u540c\u6642\u6709\u52a9\u6eb6\u89e3\u7d30\u83cc\u83cc\u819c\uff0c\u9054\u81f4\u6297\u83cc\u964d\u708e\uff0c\u5efa\u8b70\u7528\u65bc\u7642\u7a0b\u5f8c\u53ca\u5bb6\u7528\u8b77\u7406\u3002\u53e6\u5916\u6b64\u6709\u6548\u6210\u4efd\u53ef\u523a\u6fc0\u771f\u76ae\u5c64\u81a0\u539f\u86cb\u767d\u5408\u6210\uff0c\u6709\u52a9\u6e1b\u6de1\u53ca\u5e73\u6ed1\u7d30\u7d0b\uff0c\u4ee4\u808c\u819a\u7dca\u7dfb\u5149\u6ed1\u3002\u6b64\u7cbe\u83ef\u5c6cmesoestetic\u96f6\u83cc\u7cbe\u83ef\u7cfb\u5217\u4e4b\u4e00\uff0c\u63d0\u53d6\u904e\u7a0b\u65bc\u5bc6\u5c01\u5f0f\u7121\u83cc\u60c5\u6cc1\u4e0b\u9032\u884c\uff0c\u5168\u7a0b\u53d7\u56b4\u683c\u76e3\u63a7\uff0c\u78ba\u4fdd\u7cbe\u83ef\u5b89\u5168\u3001\u7d14\u6de8\u3001\u96f6\u6c61\u67d3\u3002</p>\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013\u00a0\u00a0 \u91dd\u5c0d\u654f\u611f\u76ae\u819a\u7684\u4f4e\u523a\u6fc0\u6297\u83cc\u964d\u708e\u914d\u65b9</p>\n<p>\u2013\u00a0\u00a0 \u4fc3\u9032\u76ae\u819a\u53d7\u640d\u7d44\u7e54\u7652\u5408\uff0c\u8212\u7de9\u53ca\u4fee\u5fa9\u808c\u819a</p>\n<p>\u2013\u00a0\u00a0 \u523a\u6fc0\u771f\u76ae\u5c64\u81a0\u539f\u86cb\u767d\uff0c\u6709\u52a9\u6e1b\u6de1\u5e73\u6ed1\u7d30\u7d0b</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013\u00a0\u00a0 \u7a4d\u96ea\u8349\u63d0\u53d6\u72690.5%</p>","description_zh_cn":"<p>\u79ef\u96ea\u8349\u6297\u708e\u4fee\u590d\u7cbe\u534e\u914d\u65b9\u6e29\u548c\uff0c\u4f4e\u523a\u6fc0\uff0c\u7279\u522b\u9002\u5408\u654f\u611f\u808c\u80a4\u4f7f\u7528\u3002\u79ef\u96ea\u8349\u63d0\u53d6\u7269\u6709\u4fc3\u8fdb\u76ae\u80a4\u53d7\u635f\u7ec4\u7ec7\u6108\u5408\u3001\u8212\u7f13\u53ca\u4fee\u590d\u808c\u80a4\u7684\u529f\u6548\uff1b\u540c\u65f6\u6709\u52a9\u6eb6\u89e3\u7ec6\u83cc\u83cc\u819c\uff0c\u8fbe\u81f4\u6297\u83cc\u964d\u708e\uff0c\u5efa\u8bae\u7528\u4e8e\u7597\u7a0b\u540e\u53ca\u5bb6\u7528\u62a4\u7406\u3002\u53e6\u5916\u6b64\u6709\u6548\u6210\u4efd\u53ef\u523a\u6fc0\u771f\u76ae\u5c42\u80f6\u539f\u86cb\u767d\u5408\u6210\uff0c\u6709\u52a9\u51cf\u6de1\u53ca\u5e73\u6ed1\u7ec6\u7eb9\uff0c\u4ee4\u808c\u80a4\u7d27\u81f4\u5149\u6ed1\u3002\u6b64\u7cbe\u534e\u5c5emesoestetic\u96f6\u83cc\u7cbe\u534e\u7cfb\u5217\u4e4b\u4e00\uff0c\u63d0\u53d6\u8fc7\u7a0b\u4e8e\u5bc6\u5c01\u5f0f\u65e0\u83cc\u60c5\u51b5\u4e0b\u8fdb\u884c\uff0c\u5168\u7a0b\u53d7\u4e25\u683c\u76d1\u63a7\uff0c\u786e\u4fdd\u7cbe\u534e\u5b89\u5168\u3001\u7eaf\u51c0\u3001\u96f6\u6c61\u67d3\u3002</p>\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013\u00a0\u00a0 \u9488\u5bf9\u654f\u611f\u76ae\u80a4\u7684\u4f4e\u523a\u6fc0\u6297\u83cc\u964d\u708e\u914d\u65b9</p>\n<p>\u2013\u00a0\u00a0 \u4fc3\u8fdb\u76ae\u80a4\u53d7\u635f\u7ec4\u7ec7\u6108\u5408\uff0c\u8212\u7f13\u53ca\u4fee\u590d\u808c\u80a4</p>\n<p>\u2013\u00a0\u00a0 \u523a\u6fc0\u771f\u76ae\u5c42\u80f6\u539f\u86cb\u767d\uff0c\u6709\u52a9\u51cf\u6de1\u5e73\u6ed1\u7ec6\u7eb9</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013\u00a0\u00a0 \u79ef\u96ea\u8349\u63d0\u53d6\u72690.5%</p>","description_en":"<p>A mild, low-irritation formula for sensitive skin. Centella extract supports healing, soothing and repair, helps dissolve bacterial biofilm, and stimulates dermal collagen. Part of mesoestetic's sterile serum range, extracted in a sealed, monitored process.</p>\n<p>Key benefits</p>\n<p>\u2013 Low-irritation antibacterial and anti-inflammatory formula for sensitive skin</p>\n<p>\u2013 Supports healing of damaged tissue</p>\n<p>\u2013 Stimulates collagen to help smooth fine lines</p>\n<p>Key ingredients</p>\n<p>\u2013 Centella extract 0.5%</p>","price_hkd":980,"stock":20,"image_paths":["/images/products/prod-8@2x.jpg"],"sort":222}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
  description_zh_hk text, description_zh_cn text, description_en text,
  price_hkd numeric, stock int, image_paths jsonb, sort int
)
join public.brands b on b.slug = x.brand_slug;